const meta = {
  component: Control.Number,
  parameters: {
    docs: {
      description: {
        component: "## Usage

A compact family of controls for sidebars and settings pages. Every row uses the Erbium control surface. Import `Control` from `@/registry/erbium/ui/control` and compose its typed members inside `Control.Group` or `Control.Section`.

## Number rows

`Control.Number` is a slider drawn as a full-width row: drag anywhere on it, use the arrow keys, or click the value to type an exact number. It shares its scale code with `Slider` (`@/registry/erbium/lib/slider-scale`), so the options below behave the same in both.

| Prop        | Description                                                                                                                   |
| ----------- | ----------------------------------------------------------------------------------------------------------------------------- |
| `mode`      | `"discrete"` (default) snaps to `step` or `steps`; `"continuous"` drags freely and accepts any typed number.                  |
| `steps`     | Allowed values in discrete mode, including uneven intervals. Each sits at its own position along the row.                     |
| `showSteps` | Dots for small discrete sets: each of `steps`, or each step when there are ten intervals or fewer.                            |
| `scale`     | `"linear"` (default), `"log"` for ranges across orders of magnitude (needs `min > 0`), or a custom `{ toPosition, toValue }`. |

Use `Slider` instead when the value needs labelled marks, more than one thumb, or a vertical track.

## External documentation

Explore the underlying Base UI primitives and Motion for React, used for animated control feedback.

- [Button](https://base-ui.com/react/components/button)
- [Field](https://base-ui.com/react/components/field)
- [Input](https://base-ui.com/react/components/input)
- [mergeProps](https://base-ui.com/react/utils/merge-props)
- [Radio Group](https://base-ui.com/react/components/radio-group)
- [Select](https://base-ui.com/react/components/select)
- [Slider](https://base-ui.com/react/components/slider)
- [Switch](https://base-ui.com/react/components/switch)
- [Motion for React](https://motion.dev/docs/react)",
      },
    },
    layout: "centered",
  },
  tags: ["autodocs"],
} satisfies Meta<typeof Control.Number>;

export default { ...meta, title: "Components/Control",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

