export const LogarithmicNumber: Story = {
  parameters: {
    docs: {
      description: { story: "`scale="log"` spreads values by ratio, so a frequency or zoom row gives the low end as much room as the high end. It works in both modes: discrete rows round onto `step`, continuous rows keep four significant digits. Arrow keys move 1% of the row (10% with Shift). The value editor still accepts any in-range number, and a log scale needs `min` above zero." },
      source: { code: "import { Control } from "@/registry/erbium/ui/control";

const hertz = (value: number) => (value >= 1000 ? `${value / 1000} kHz` : `${value} Hz`);

export default function ControlLogarithmicNumberExample() {
  return (
    <Control.Group className="w-72">
      <Control.Number
        label="Frequency"
        scale="log"
        min={20}
        max={20_000}
        step={1}
        defaultValue={440}
        formatValue={hertz}
      />
      <Control.Number
        label="Scale"
        scale="log"
        mode="continuous"
        min={0.01}
        max={100}
        defaultValue={1}
      />
    </Control.Group>
  );
}
" },
    },
  },
  render: LogarithmicNumberExample,
};

